sections.example:
# Repetition example
for i in range(3):
    print('Calculating...')

# Using if, elif and else
x = 42
if x < 0:
    print('Negative')
elif x == 0:
    print('Zero')
else:
    print('Positive')

# Using range()
for i in range(3):
    print(i)  # Prints: 0, 1, 2

for n in range(2, 4):
    for x in range(2, n):
        if n % x == 0:
            print(n, 'is not prime')
            break
    else:
        # Executed if the inner loop finishes without breaking
        print(n, 'is a prime number')

fruits = ['Apple', 'Banana', 'Orange']
search = 'Grape'

for fruit in fruits:
    if fruit == search:
        print('Found the fruit!')
        break
else:
    # Runs if break is never hit!
    print('We did not have this fruit in the list.')

