def calculate_average(grade1, grade2=7.0):
    return (grade1 + grade2) / 2

print(calculate_average(9.0))  # Uses default grade2 (7.0) -> Average 8.0

try:
    res = 10 / 0
except ZeroDivisionError:
    print('Division by zero prevented!')
finally:
    print('End')

class Dog:
    def __init__(self, name):
        self.name = name
    def bark(self):
        return f'{self.name} says: Woof Woof!'

dog = Dog('Rex')
print(dog.bark())
